//! Agent input: `AgentParams` (untrusted, all strings) → `validate()` → `NewAgent` (typed).
//! Generated by `cargo offrails generate resource agents name:string description:text`.

use serde::Deserialize;

use super::Model;
use crate::models::Errors;

/// Untrusted input from the agent form. This struct IS the permit list: no owner. All strings, so a
/// failed submit re-renders exactly what was typed.
#[derive(Debug, Default, Clone, Deserialize)]
pub struct AgentParams {
    #[serde(default)]
    pub name: String,
    #[serde(default)]
    pub description: String,
}

/// Validated, typed values. Only `AgentParams::validate` makes one.
#[derive(Debug, Clone, PartialEq)]
pub struct NewAgent {
    pub name: String,
    pub description: String,
}

impl AgentParams {
    /// Rails wording: "can't be blank", "is too long (maximum is N characters)".
    pub fn validate(&self) -> Result<NewAgent, Errors> {
        let mut errors = Errors::default();
        let name = self.name.trim();
        if name.is_empty() {
            errors.add("name", "can't be blank");
        } else if name.chars().count() > 255 {
            errors.add("name", "is too long (maximum is 255 characters)");
        }
        let description = self.description.trim();
        if description.is_empty() {
            errors.add("description", "can't be blank");
        } else if description.chars().count() > 100000 {
            errors.add("description", "is too long (maximum is 100000 characters)");
        }
        errors.into_result(|| NewAgent {
            name: name.to_owned(),
            description: description.to_owned(),
        })
    }
}

/// Prefills the edit form.
impl From<&Model> for AgentParams {
    fn from(r: &Model) -> Self {
        Self {
            name: r.name.clone(),
            description: r.description.clone(),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn valid() -> AgentParams {
        AgentParams {
            name: "Name".into(),
            description: "Description text".into(),
        }
    }

    #[test]
    fn valid_params_validate() {
        assert!(valid().validate().is_ok(), "{:?}", valid().validate());
    }

    #[test]
    fn required_fields_cant_be_blank() {
        let errors = AgentParams::default().validate().unwrap_err();
        assert_eq!(errors.on("name"), ["can't be blank"]);
        assert_eq!(errors.on("description"), ["can't be blank"]);
    }

    #[test]
    fn strings_have_a_maximum_length() {
        let at_max = AgentParams {
            name: "x".repeat(255),
            ..valid()
        };
        assert!(at_max.validate().is_ok());
        let over = AgentParams {
            name: "x".repeat(256),
            ..valid()
        };
        assert_eq!(
            over.validate().unwrap_err().on("name"),
            ["is too long (maximum is 255 characters)"]
        );
        let at_max = AgentParams {
            description: "x".repeat(100000),
            ..valid()
        };
        assert!(at_max.validate().is_ok());
        let over = AgentParams {
            description: "x".repeat(100001),
            ..valid()
        };
        assert_eq!(
            over.validate().unwrap_err().on("description"),
            ["is too long (maximum is 100000 characters)"]
        );
    }
}
